#include <assert.h>
#include <stdio.h>
#define HOST_TEST
#include "../gba/main.c"
static void packet(unsigned type,unsigned n,unsigned *data){unsigned h=(type<<8)|n,s=h;receive(0xa55a);receive(h);for(unsigned i=0;i<n;i++){receive(data[i]);s+=data[i];}receive((-s)&65535);}
static void submit(unsigned id,const uint16_t *s,unsigned n,int bad){for(unsigned off=0;off<n;){unsigned size=n-off;if(size>25)size=25;unsigned d[29]={id,0,off,n};for(unsigned i=0;i<size;i++)d[4+i]=s[off+i];packet(0x22,size+4,d);off+=size;}unsigned c[3]={id,0,text_crc(id,n,s)^bad};packet(0x23,3,c);}
int main(int argc,char **argv){(void)argv;draw_screen();if(argc>1){unsigned w;while(scanf("%x",&w)==1){receive(w);draw_step();}for(int i=0;i<80;i++)draw_step();printf("%u %u %u\n",ack_id,ack_crc,message_length);return 0;}uint16_t jp[]={0x6b21,0x306b,0x8a71,0x3059,0x3053,0x3068,0x3002,0x3042,0x308a,0x304c,0x3068,0x3046};submit(1,jp,12,1);assert(!rendering);submit(2,jp,12,0);assert(rendering&&!ack_valid);for(int i=0;i<79;i++)draw_step();assert(!ack_valid);draw_step();assert(ack_valid&&ack_id==2);unsigned syncs=0;for(int i=0;i<100;i++)if(next_word(0)==0xa55a)syncs++;assert(syncs>3);submit(3,jp,12,0);draw_step();submit(4,jp,12,0);for(int i=0;i<80;i++)draw_step();assert(ack_id==4);uint16_t full[65];for(int i=0;i<65;i++)full[i]=0x3042;submit(5,full,65,0);for(int i=0;i<80;i++)draw_step();assert(ack_id==5&&message_length==65);uint16_t invalid[]={0xd800};submit(6,invalid,1,0);assert(!rendering&&ack_id==5);submit(7,jp,12,0);for(int i=0;i<80;i++)draw_step();FILE *f=fopen("/tmp/parade-japanese.ppm","wb");assert(f);fprintf(f,"P6\n240 160\n255\n");for(int i=0;i<240*160;i++){unsigned c=SCREEN[i];fputc((c&31)*255/31,f);fputc(((c>>5)&31)*255/31,f);fputc(((c>>10)&31)*255/31,f);}fclose(f);puts("receiver: Japanese, CRC rejection, delayed/repeated ACK, superseding draw, 65 glyphs passed");}
